func _run_tests() -> void:
	# 1. Controllo schema della storia
	var schema_path := "res://story/story_schema.json"
	if not check("schema_exists", FileAccess.file_exists(schema_path), "Il file res://story/story_schema.json deve esistere"):
		return

	var schema_file := FileAccess.open(schema_path, FileAccess.READ)
	if not check("schema_open", schema_file != null, "Impossibile aprire res://story/story_schema.json"):
		return

	var schema_data: Variant = JSON.parse_string(schema_file.get_as_text())
	if not check("schema_valid", schema_data is Dictionary, "Il file story_schema.json deve contenere un oggetto JSON valido"):
		return

	var schema: Dictionary = schema_data
	var scenes: Variant = schema.get("scenes", [])
	var endings: Variant = schema.get("endings", [])
	var variables: Variant = schema.get("variables", {})
	var branches: Variant = schema.get("branches", schema.get("choices", []))
	var conditions: Variant = schema.get("conditions", [])

	check("schema_scenes", scenes is Array and scenes.size() >= 3, "Lo schema deve contenere almeno 3 scene")
	check("schema_endings", endings is Array and endings.size() >= 2, "Lo schema deve contenere almeno 2 finali distinti")

	var var_keys: Array = []
	if variables is Dictionary:
		var_keys = variables.keys()
	elif variables is Array:
		var_keys = variables
	check("schema_variables", var_keys.size() >= 1, "Lo schema deve definire almeno una variabile")

	var var_used := false
	if conditions is Array:
		for cond in conditions:
			if cond is Dictionary and var_keys.has(cond.get("variable", "")):
				var_used = true
				break
	if not var_used and branches is Array:
		for br in branches:
			if br is Dictionary and br.has("options") and br["options"] is Array:
				for opt in br["options"]:
					if opt is Dictionary and opt.has("condition") and opt["condition"] is Dictionary:
						if var_keys.has(opt["condition"].get("variable", "")):
							var_used = true
							break
	check("schema_condition_var", var_used, "Almeno una condizione deve verificare una delle variabili dichiarate nello schema")

	# 2. Controllo registro asset
	var reg_path := "res://assets/asset_register.json"
	if not check("reg_exists", FileAccess.file_exists(reg_path), "Il file res://assets/asset_register.json deve esistere"):
		return

	var reg_file := FileAccess.open(reg_path, FileAccess.READ)
	if not check("reg_open", reg_file != null, "Impossibile aprire res://assets/asset_register.json"):
		return

	var reg_data: Variant = JSON.parse_string(reg_file.get_as_text())
	if not check("reg_valid", reg_data is Dictionary or reg_data is Array, "Il file asset_register.json deve contenere un JSON valido"):
		return

	var entries: Array = []
	if reg_data is Dictionary:
		var raw_assets = reg_data.get("assets", [])
		if raw_assets is Array:
			entries = raw_assets
	elif reg_data is Array:
		entries = reg_data

	check("reg_count", entries.size() >= 4, "Il registro deve contenere almeno 4 asset (trovati: %d)" % entries.size())

	var categories: Array[String] = []
	var missing_files: Array[String] = []
	var incomplete_entries := 0

	for entry in entries:
		if not entry is Dictionary:
			continue
		var a_path: String = String(entry.get("path", ""))
		var cat: String = String(entry.get("category", "")).to_lower()
		var author: String = String(entry.get("author", ""))
		var license: String = String(entry.get("license", ""))

		if cat != "" and not categories.has(cat):
			categories.append(cat)
		if author.is_empty() or license.is_empty() or a_path.is_empty():
			incomplete_entries += 1
		if not FileAccess.file_exists(a_path) and not ResourceLoader.exists(a_path):
			missing_files.append(a_path)

	check("reg_fields", incomplete_entries == 0, "Tutte le voci del registro devono specificare path, author e license")
	check("reg_files_exist", missing_files.is_empty(), "Tutti i file nel registro devono esistere sul disco (mancanti: %s)" % ", ".join(missing_files))

	var has_bg := categories.has("background")
	var has_char := categories.has("character") or categories.has("sprite")
	var has_music := categories.has("music")
	var has_sfx := categories.has("sfx") or categories.has("sound")
	check("reg_categories", has_bg and has_char and has_music and has_sfx, "Il registro deve coprire background, character, music, sfx")

	# 3. Controllo personaggi CharacterData nella cartella dedicata
	var char_dir_path := "res://story/characters"
	var valid_chars: Array[CharacterData] = []
	if DirAccess.dir_exists_absolute(char_dir_path):
		var dir := DirAccess.open(char_dir_path)
		if dir:
			dir.list_dir_begin()
			var fname := dir.get_next()
			while fname != "":
				if not dir.current_is_dir() and fname.ends_with(".tres"):
					var res: Resource = ResourceLoader.load(char_dir_path + "/" + fname)
					if res is CharacterData:
						var cdata := res as CharacterData
						if not cdata.display_name.is_empty() and not cdata.expressions.is_empty():
							valid_chars.append(cdata)
				fname = dir.get_next()

	check("characters_ready", valid_chars.size() >= 2, "La cartella res://story/characters/ deve contenere almeno 2 risorse CharacterData con display_name ed expressions (trovate: %d)" % valid_chars.size())
"
